ON CONFLICT (item_key) DO UPDATE SET
    name = EXCLUDED.name,
    slot = EXCLUDED.slot,
    equip_group = EXCLUDED.equip_group,
    layer_order = EXCLUDED.layer_order,
    asset_path = EXCLUDED.asset_path,
    is_default = EXCLUDED.is_default,
    is_starter = EXCLUDED.is_starter,
    is_tradeable = EXCLUDED.is_tradeable,
    is_sellable = EXCLUDED.is_sellable,
    rarity = EXCLUDED.rarity,
    base_price = EXCLUDED.base_price,
    release_status = EXCLUDED.release_status,
    metadata = public.avatar_items.metadata || EXCLUDED.metadata,
    category = EXCLUDED.category,
    parts = EXCLUDED.parts,
    dyes = EXCLUDED.dyes,
    hides = EXCLUDED.hides,
    occupies = EXCLUDED.occupies,
    stack_order = EXCLUDED.stack_order
WHERE public.avatar_items.art_version = 3;

-- Items no longer in pixel-avatar/ stop being sold or granted.
UPDATE public.avatar_items
SET release_status = 'retired', is_starter = FALSE, is_default = FALSE
WHERE art_version = 3 AND item_key NOT IN ('bat_buddy', 'bat_wings', 'bedsheet_ghost', 'body_ghost', 'body_kid', 'body_skull', 'body_zombie', 'boots', 'candy_pail', 'cat_ears', 'devil_horns', 'hair_bob', 'hair_cowlick', 'hair_crop', 'hair_curls', 'hair_fringe', 'hair_long_locks', 'hair_long_straight', 'hair_mohawk', 'hair_mop', 'hair_pigtails', 'hair_ponytail', 'hair_side_part', 'hair_space_buns', 'hair_spikes', 'jack_o_lantern_head', 'jeans', 'moonlit_graveyard', 'open_jacket', 'pointy_witch_hat', 'pumpkin_pal', 'purdue_beanie', 'purdue_p_cap', 'purdue_p_crewneck', 'purdue_pennant', 'rosy_cheeks', 'round_glasses', 'skeleton_tee', 'skull_mask', 'sneakers', 'soul_lantern_px', 'striped_scarf', 'striped_sweater', 'tall_top_hat', 'tee', 'trousers', 'vampire_cape', 'zip_jacket');
